// Solution 3: Batch resolve in parent
Query: {
  users: async (_, { ids }) => {
    const users = await db.users.findAll({ where: { id: ids } });
    const posts = await db.posts.findAll({ where: { userId: ids } });
    return users.map(u => ({ ...u, posts: posts.filter(p => p.userId === u.id) }));
  }
}

