const context = async ({ req }) => {
  const ip = req.ip;
  const key = `gql:${ip}:${Math.floor(Date.now() / 60000)}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, 60);

  if (count > 100) {
