Pagination:
type Query {
  users(first: Int!, after: String): UserConnection!
}

type UserConnection {
  edges: [UserEdge!]!
  pageInfo: PageInfo!
  totalCount: Int!
}

type UserEdge {
  node: User!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  hasPreviousPage: Boolean!
  startCursor: String
  endCursor: String
}

// Resolver
users: async (_, { first, after }, { db }) => {
  const afterId = after ? Buffer.from(after, 'base64').toString() : null;

  const users = await db.users.findAll({
    limit: first + 1,
    where: afterId ? { id: { [Op.gt]: afterId } } : {},
    order: [['id', 'ASC']]
  });

  const hasNextPage = users.length > first;
  const nodes = hasNextPage ? users.slice(0, first) : users;

  return {
    edges: nodes.map(user => ({
      node: user,
      cursor: Buffer.from(String(user.id)).toString('base64')
    })),
    pageInfo: {
      hasNextPage,
      hasPreviousPage: !!after,
      startCursor: nodes[0] && Buffer.from(String(nodes[0].id)).toString('base64'),
      endCursor: nodes[nodes.length - 1] && Buffer.from(String(nodes[nodes.length - 1].id)).toString('base64')
    },
    totalCount: await db.users.count()
  };
}

