// Manual batching example
const batch = (items, batchSize, fn) => {
  const batches = [];
  for (let i = 0; i < items.length; i += batchSize) {
    batches.push(fn(items.slice(i, i + batchSize)));
  }
  return Promise.all(batches).then(results => results.flat());
};

