const { PubSub } = require('graphql-subscriptions');
const pubsub = new PubSub();

const typeDefs = `
  type Subscription {
    messageAdded(roomId: ID!): Message!
    userOnline: User!
  }
`;

const resolvers = {
  Subscription: {
    messageAdded: {
      subscribe: (_, { roomId }) => pubsub.asyncIterator(`MESSAGE_ADDED_${roomId}`)
    },
    userOnline: {
      subscribe: () => pubsub.asyncIterator('USER_ONLINE')
    }
  },
  Mutation: {
    sendMessage: async (_, { roomId, content }, { db, user }) => {
      const message = await db.messages.create({ roomId, content, userId: user.id });
      pubsub.publish(`MESSAGE_ADDED_${roomId}`, { messageAdded: message });
      return message;
    }
  }
};

